/* Generated from claude.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='claude'],
[data-ui-theme='claude'] {
  color-scheme: light;
  --ui-background: oklch(0.98 0.01 95.10);
  --ui-foreground: oklch(0.34 0.03 95.72);
  --ui-card: oklch(0.98 0.01 95.10);
  --ui-card-foreground: oklch(0.19 0.00 106.59);
  --ui-popover: oklch(1.00 0 0);
  --ui-popover-foreground: oklch(0.27 0.02 98.94);
  --ui-primary: oklch(0.62 0.14 39.04);
  --ui-primary-foreground: oklch(1.00 0 0);
  --ui-secondary: oklch(0.92 0.01 92.99);
  --ui-secondary-foreground: oklch(0.43 0.02 98.60);
  --ui-muted: oklch(0.955 0.0124 91.52);
  --ui-muted-foreground: oklch(0.61 0.01 97.42);
  --ui-accent: oklch(0.92 0.01 92.99);
  --ui-accent-foreground: oklch(0.27 0.02 98.94);
  --ui-destructive: oklch(0.19 0.00 106.59);
  --ui-destructive-foreground: oklch(1.00 0 0);
  --ui-border: oklch(0.9078 0.0094 106.59);
  --ui-input: oklch(0.76 0.02 98.35);
  --ui-ring: oklch(0.59 0.17 253.06);
  --ui-chart-1: oklch(0.56 0.13 43.00);
  --ui-chart-2: oklch(0.69 0.16 290.41);
  --ui-chart-3: oklch(0.88 0.03 93.13);
  --ui-chart-4: oklch(0.88 0.04 298.18);
  --ui-chart-5: oklch(0.56 0.13 42.06);
  --ui-sidebar: oklch(0.97 0.01 98.88);
  --ui-sidebar-foreground: oklch(0.36 0.01 106.65);
  --ui-sidebar-primary: oklch(0.62 0.14 39.04);
  --ui-sidebar-primary-foreground: oklch(0.99 0 0);
  --ui-sidebar-accent: oklch(0.2221 0 0);
  --ui-sidebar-accent-foreground: oklch(0.33 0 0);
  --ui-sidebar-border: oklch(0.94 0 0);
  --ui-sidebar-ring: oklch(0.77 0 0);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Source Serif 4', ui-serif, serif;
  --ui-font-heading: 'Geist', ui-sans-serif, sans-serif;
  --ui-font-mono: 'JetBrains Mono', ui-monospace, monospace;
  --ui-shadow-control: 0 1px 3px 0px oklch(0.00 0 0 / 0.05);
  --ui-shadow-panel:
    0 1px 3px 0px oklch(0.00 0 0 / 0.10), 0 4px 6px -1px oklch(0.00 0 0 / 0.10);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

:root.dark,
[data-ui-preset='claude'].dark,
[data-ui-theme='claude'].dark {
  color-scheme: dark;
  --ui-background: oklch(0.27 0.00 106.64);
  --ui-foreground: oklch(0.81 0.01 93.01);
  --ui-card: oklch(0.27 0.00 106.64);
  --ui-card-foreground: oklch(0.98 0.01 95.10);
  --ui-popover: oklch(0.31 0.00 106.60);
  --ui-popover-foreground: oklch(0.92 0.00 106.48);
  --ui-primary: oklch(0.67 0.13 38.76);
  --ui-primary-foreground: oklch(1.00 0 0);
  --ui-secondary: oklch(0.98 0.01 95.10);
  --ui-secondary-foreground: oklch(0.31 0.00 106.60);
  --ui-muted: oklch(0.22 0.00 106.71);
  --ui-muted-foreground: oklch(0.77 0.02 99.07);
  --ui-accent: oklch(0.21 0.01 95.42);
  --ui-accent-foreground: oklch(0.97 0.01 98.88);
  --ui-destructive: oklch(0.64 0.21 25.33);
  --ui-destructive-foreground: oklch(1.00 0 0);
  --ui-border: oklch(0.36 0.01 106.89);
  --ui-input: oklch(0.43 0.01 100.22);
  --ui-ring: oklch(0.59 0.17 253.06);
  --ui-chart-1: oklch(0.56 0.13 43.00);
  --ui-chart-2: oklch(0.69 0.16 290.41);
  --ui-chart-3: oklch(0.21 0.01 95.42);
  --ui-chart-4: oklch(0.31 0.05 289.32);
  --ui-chart-5: oklch(0.56 0.13 42.06);
  --ui-sidebar: oklch(0.24 0.00 67.71);
  --ui-sidebar-foreground: oklch(0.81 0.01 93.01);
  --ui-sidebar-primary: oklch(0.33 0 0);
  --ui-sidebar-primary-foreground: oklch(0.99 0 0);
  --ui-sidebar-accent: oklch(0.17 0.00 106.62);
  --ui-sidebar-accent-foreground: oklch(0.81 0.01 93.01);
  --ui-sidebar-border: oklch(0.94 0 0);
  --ui-sidebar-ring: oklch(0.77 0 0);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Source Serif 4', ui-serif, serif;
  --ui-font-heading: 'Geist', ui-sans-serif, sans-serif;
  --ui-font-mono: 'JetBrains Mono', ui-monospace, monospace;
  --ui-shadow-control: 0 1px 3px 0px oklch(0.00 0 0 / 0.05);
  --ui-shadow-panel:
    0 1px 3px 0px oklch(0.00 0 0 / 0.10), 0 4px 6px -1px oklch(0.00 0 0 / 0.10);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}
